// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2018, "2-3", [{"author":"О. Подлесская","question":"В книге М. Ибрагимбекова «Пусть он останется с нами» читаем: «Бабушка пожелала нам доброго аппетита, и мы начали обедать». А как сейчас чаще говорят?","choices":["<em>хорошего аппетита</em>","<em>приятного аппетита</em>","<em>славного аппетита</em>","<em>сладкого аппетита</em>","<em>большого аппетита</em>."],"key":"Б","review":["Пожелание перед обедом","Вспомни, что говорят, когда все уже сели за стол и собираются есть. Эта фраза звучит сразу перед началом трапезы.","Обычно говорят «Приятного аппетита!». Именно это пожелание сейчас услышишь чаще всего."]},{"author":"И. Рубанов","question":"С какой из этих букв <strong>не</strong> начинаются русские имена?","choices":["<em>А</em>","<em>Е</em>","<em>И</em>","<em>Ы</em>","<em>Ю</em>."],"key":"Г","review":["Первые буквы имён","Вспомни несколько полных имён. Александр начинается на «А», Елена — на «Е», Иван — на «И», Юлия — на «Ю».","Начальная «Ы» не встречается в русских именах. Это единственная буква из списка, к которой такое имя не подбирается."]},{"author":"О. Подлесская","question":"Найдите лишнее по смыслу слово в этом ряду.","choices":["<em>большой</em>","<em>указательный</em>","<em>средний</em>","<em>безымянный</em>","<em>последний</em>."],"key":"Д","review":["Ряд слов по смыслу","Попробуй добавить слово «палец». На руке есть большой, указательный, средний и безымянный пальцы.","У пятого пальца тоже есть имя — мизинец. «Последний» может обозначать место в порядке перечисления, но в число названий пальцев не входит."]},{"author":"Л. Фёдорова","question":"<em>Ни в сказке сказать, ни ______ описать</em>. Что мы пропустили?","choices":["<em>стихами</em>","<em>словами</em>","<em>красками</em>","<em>пером</em>","<em>топором.</em>"],"key":"Г","review":["Сказочное выражение","В первой половине говорится о том, что красоту трудно передать словами, даже в сказке. Во второй половине нужен предмет, которым можно записать описание.","Таким предметом раньше служило перо. Полное выражение звучит «Ни в сказке сказать, ни пером описать»."]},{"author":"И. Рубанов","question":"Сколько чисел от 1 до 100 называются словами, состоящими из трёх букв?","choices":["одно","два","три","четыре","пять."],"key":"В","review":["Числа из трёх букв","Проверь названия от одного до десяти. По три буквы только в словах «два» и «три», остальные названия длиннее.","Числа от 11 до 99 тоже называются более длинными словами, иногда сразу несколькими. А «сто» состоит из трёх букв. Получается три числа."]},{"author":"Б. Иомдин","question":"В каком предложении можно заменить <em>всякий</em> на <em>каждый</em>?","choices":["<em>Болтали о всякой всячине</em>.","<em>На всякий случай позвони</em>.","<em>Ходят тут всякие.</em>","<em>Всякий раз удивляюсь</em>.","<em>Смотрел без всякого интереса</em>."],"key":"Г","review":["Слова «всякий» и «каждый»","Проверь смысл слова «всякий». «Всякая всячина» значит «разные вещи», «на всякий случай» — «для подстраховки», «без всякого интереса» — «совсем без интереса». В «Ходят тут всякие» речь о каких-то людях.","«Всякий раз» означает «при всяком новом случае». Здесь можно сказать «Каждый раз удивляюсь», и смысл сохранится."]},{"author":"Е. Бикмаев","question":"Их у человека больше двух. Что это?","choices":["ресницы","брови","глаза","уши","щёки."],"key":"А","review":["Чего больше двух","Назови то, что бывает парами. У человека обычно два глаза, два уха, две брови и две щеки.","Даже у одного глаза несколько ресниц. Поэтому ресниц больше двух."]},{"author":"Б. Иомдин","question":"В мультфильме «Котёнок по имени Гав» котёнок Гав беседует с большим чёрным котом:\n<em>— А кто это — хозяин?</em>\n<em>— Хозяин? Хозяин — это… это… Эх, да разве расскажешь?</em>\n<em>— А где его взять, хозяина? А где они водятся, эти хозяины?</em>\nА как правильно?","choices":["<em>хозяины</em>","<em>хозяине</em>","<em>хозяева</em>","<em>хозяевы</em>","<em>хозяивы</em>."],"key":"В","review":["Котёнок и хозяин","Гав знает слово «хозяин», но спрашивает сразу о нескольких людях. Подбери правильную форму, ответив на вопрос «кто?» во множественном числе.","Правильно «хозяева», как в выражении «хозяева дома». Гав мог бы спросить «А где водятся эти хозяева?»"]},{"author":"И. Рубанов","question":"Монету в 15 копеек раньше называли <em>пятиалтынным</em>. А какую монету тогда называли <em>алтыном</em>?","choices":["1 копейку","2 копейки","3 копейки","5 копеек","10 копеек."],"key":"В","review":["Монета в 15 копеек","Выдели часть «пяти-» в слове «пятиалтынный». Она показывает, что монета стоит пять алтынов.","Пять алтынов равны 15 копейкам. Раздели 15 на 5, и получишь цену одного алтына — 3 копейки."]},{"author":"Б. Иомдин","question":"Какого слова <strong>не</strong> существует?","choices":["<em>лгун</em>","<em>лжец</em>","<em>врун</em>","<em>враль</em>","<em>лгаль</em>."],"key":"Д","review":["Как называют обманщика","Вспомни два глагола про обман. С «лгать» связаны слова «лгун» и «лжец», а с «врать» — «врун» и «враль».","Слово «лгаль» похоже на «враль», но такой формы в русском литературном языке нет. От «лгать» можно сказать «лгун»."]},{"author":"Б. Иомдин","question":"<em>— Меня тоже _____ зовут. Так уж придётся тебе побыть _____.</em>\n<em>Чтобы не путали.</em>\nВ этом отрывке мы пропустили два имени. А из какой книги он взят?","choices":["«Саша и Маша»","«Саша и Шура»","«Руслан и Людмила»","«Про Веру и Анфису»","«Чук и Гек»."],"key":"Б","review":["Два имени для героев","В словах «меня тоже» слышно, что у героев одинаковое имя. Чтобы различать их, один герой предлагает воспользоваться другой формой того же имени.","Сашей и Шурой могут называть Александра. Только в названии «Саша и Шура» стоят две формы одного имени, поэтому подходит эта книга."]},{"author":"Б. Иомдин","question":"Что <strong>не</strong> обязательно красного цвета?","choices":["красная ручка","красный помидор","красная рубашка","красная кровь","красные чернила."],"key":"А","review":["Предметы красного цвета","Представь предметы из вариантов. У красной рубашки и красного помидора цвет виден снаружи, а слова «красные чернила» и «красная кровь» тоже прямо говорят о цвете жидкости.","Красная ручка может писать красным, даже если её корпус синий или прозрачный. В этом случае слово «красная» сообщает цвет чернил."]},{"author":"Б. Иомдин и Ю. Халеева","question":"Ребята играли, подбирая персонажей с именами на ту же букву, что и их имена:\n— Алиса Селезнёва!\n— Барон Мюнхгаузен!\n— Витя Малеев!\n— Мэри Поппинс!\n— Том Сойер!\nКто нарушил это правило?","choices":["Аня","Боря","Витя","Маша","Таня."],"key":"Б","review":["Игра в имена персонажей","Сравни первые буквы имён. К Ане подходит Алиса, к Вите — Витя, к Маше — Мэри, к Тане — Том.","«Барон» — титул, а не имя персонажа. Поэтому Боря, назвав барона Мюнхгаузена, взял слово на «Б», которое не является именем."]},{"author":"М. Рубинштейн","question":"Некоторые смартфоны предлагают заменить текст на картинку: например, вы начинаете набирать слово <em>домашний</em> и, как только вы набираете <em>дом</em>, появляется картинка с изображением домика. Если вы продолжаете печатать слово, то картинка пропадает. При наборе какого слова никакая картинка не появляется?","choices":["<em>рукавица</em>","<em>который</em>","<em>носовой</em>","<em>хлебать</em>","<em>русский</em>."],"key":"Д","review":["Картинка из набранных букв","Останавливай набор в разных местах. В начале «рукавица» есть «рука», «который» начинается с «кот», «носовой» — с «нос», а «хлебать» — с «хлеб».","Начало слова «русский» не даёт такого короткого названия предмета, животного или части тела. По правилу из примера картинка не появится."]},{"author":"И. Иткин","question":"Настоящая фамилия этого писателя — Гриневский. А нам он известен как...","choices":["Фёдор Достоевский","Александр Грибоедов","Аполлон Григорьев","Александр Грин","Геннадий Гор."],"key":"Г","review":["Настоящая фамилия писателя","Сравни фамилию Гриневский с именами в списке. Если убрать «-евский», начало «Грин» целиком сохраняется.","Александр Степанович Гриневский публиковал свои произведения под именем Александр Грин. Это имя и нужно выбрать."]},{"author":"С. Переверзева","question":"Рассматривая картинки с животными, маленький Лёва называет одного детёныша словом <em>ребёнок</em>. А кто мама этого детёныша?","choices":["лошадь","свинья","коза","корова","овца."],"key":"А","review":["Лёва называет детёныша","Назови детёнышей из списка. У свиньи поросёнок, у козы козлёнок, у коровы телёнок, у овцы ягнёнок, у лошади жеребёнок.","Если отбросить от «жеребёнка» первый слог «же-», остаётся «ребёнок». Поэтому мама на картинке — лошадь."]},{"author":"Е. Муравенко","question":"В начале сказки Льва Толстого «Три медведя» читаем: «В домике было две комнаты: одна столовая, другая спальня». В середине сказки говорится, что девочка пошла в другую горницу. Что такое <em>горница</em>?","choices":["то же, что комната","то же, что столовая","то же, что спальня","то же, что гостиная","то же, что прихожая."],"key":"А","review":["Горница в домике медведей","В начале сказки сказано, что в доме всего две комнаты. «Другая горница» означает, что девочка из одной комнаты перешла в другую.","И столовую, и спальню здесь можно назвать горницей. Значит, «горница» в сказке обозначает комнату."]},{"author":"Б. Иомдин и Ю. Халеева","question":"В стихотворении Майкла Розена «Идём ловить медведя» (перевод Григория Кружкова) описан путь героев, сопровождаемый такими звуками: (1) <em>Шурх, шорх!</em> (2) <em>Плих, плюх!</em> (3) <em>Хли-и-п, хлю-у-уп!</em> (4) <em>Хрум, хрясь!</em> (5) <em>Ууууу, вууу!</em>\nВ каком порядке герои преодолевают препятствия?","choices":["лес, трава, болото, метель, река","трава, река, болото, лес, метель","лес, болото, река, метель, трава","лес, река, болото, метель, трава","трава, река, лес, болото, метель."],"key":"Б","review":["Звуки на пути к медведю","Сопоставь первые три звука с тем, как героям приходится идти. «Шурх, шорх» — шорох травы, «плих, плюх» — брызги в реке, «хли-и-п, хлю-у-уп» — хлюпанье грязи в болоте.","Под ногами в лесу ветки трещат «хрум, хрясь», а в метели завывает ветер «ууууу, вууу». Выходит порядок «трава, река, болото, лес, метель»."]},{"author":"Б. Иомдин и Ю. Халеева","question":"По какому запросу в интернете можно найти аппарат для приготовления пирожков?","choices":["<em>Дашины пирожки</em>","<em>Сашины пирожки</em>","<em>Машины пирожки</em>","<em>Мишины пирожки</em>","<em>Яшины пирожки</em>."],"key":"В","review":["Запрос про пирожки","Прочитай варианты так, словно пирожки у кого-то дома. «Дашины», «Сашины», «Машины», «Мишины» и «Яшины» могут показывать, кому они принадлежат.","У слова «машины» есть и другой смысл — устройства для работы. Слова «машины» и «пирожки» вместе помогут поиску найти аппарат."]},{"author":"Л. Фёдорова","question":"Я люблю лишь воробьёв, (1)\nНе люблю я голубьёв! (2)\n<...>\nЯ люблю лишь воробей, (3)\nНе люблю я голубей! (4)\nТРУДНО-ТО КАК, А? (5)\nВ каких строчках воробей из стихотворения Г. Кружкова «Как воробей стихи сочинял» сделал ошибки?","choices":["во всех","только в (2)","только в (3)","только в (2) и (3)","ни в каких строчках нет ошибок."],"key":"Г","review":["Воробей сочиняет стихи","После «люблю» спроси «кого?». Правильные ответы — «воробьёв» и «голубей». Воробей пытался заставить эти слова рифмоваться, изменяя формы.","В строке 2 он ошибся, написав «голубьёв», а в строке 3 — «воробей». В строках 1 и 4 формы правильные, а в строке 5 есть только восклицание."]},{"author":"Л. Фёдорова","question":"Играя с именами, Миша заметил, что, если прочесть имя с конца и выбросить одну букву, может получиться слово. Из какого имени так слово получить <strong>нельзя</strong>?","choices":["<em>Глеб</em>","<em>Максим</em>","<em>Антон</em>","<em>Артём</em>","<em>Ефим</em>. 2–3классы"],"key":"Г","review":["Имена задом наперёд","Запиши имена справа налево и убери лишнюю букву. Из «белг» получится «бег», из «мискам» — «миска», из «нотна» — «нота», из «мифе» — «миф».","«Артём» превращается в «мётра». Если убрать последнюю «а», останется «мётр», но слово «метр» пишется с «е». При удалении любой другой буквы знакомого слова тоже не выходит."]},{"author":"С. Переверзева и И. Рубанов","question":"В стихотворении Наили Галямовой «Нежная песня» есть строчка: <em>Косы</em> <<em>…</em>><em>,</em> <em>встану</em> <<em>…</em>>. На слух пропуски заполняются одинаково. Чем собирается заняться героиня песни после того, как приведёт в порядок волосы?","choices":["чтением","готовкой","стиркой","глажкой","спортом."],"key":"Б","review":["Косы и похожие звуки","Подумай, что можно сделать с косами. Подходит фраза «Косы заплету». Теперь прочитай «заплету́» и послушай звуки без оглядки на написание.","Так же звучит «за плиту́». Получается, что героиня встанет за плиту и будет готовить."]},{"author":"Е. Муравенко","question":"Вот двустишия из книжки А. Шибаева о буквах и словах:\nЗабодал меня котёл —\nНа него я очень зол.\n\nПосмотрите-ка, ребятки:\nРаки выросли на грядке!\nВ два слова вместо правильных согласных забрались другие. Найдите эти слова, замените в них неправильные согласные правильными и выберите слово с этими правильными согласными.","choices":["<em>тема</em>","<em>зима</em>","<em>роза</em>","<em>море</em>","<em>тир</em>."],"key":"Б","review":["Ошибки в двух двустишиях","Найди странности в стихах. Вместо «котёл» нужно «козёл», ведь у него есть рога. А вместо «раки» — «маки», ведь на грядке растут цветы.","При исправлении получились согласные «з» и «м». Обе буквы есть в слове «зима», поэтому подходит оно."]},{"author":"Е. Бикмаев","question":"О чём реже всего можно услышать на уроках математики?","choices":["о единицах","о десятках","о сотках","о тысячах","о числах."],"key":"В","review":["Слова с урока математики","Вспомни, из чего складываются числа. В числе 1234 есть одна тысяча, две сотни, три десятка и четыре единицы.","В счёте говорят «сотня», а «сотка» обычно означает площадь участка в сто квадратных метров. На уроках математики слово «сотка» слышится реже других данных слов."]},{"author":"А. Леонтьева","question":"Маленькая Света рассказывает маме: <em>Мы сегодня с бабушкой видели злой поезд.</em> <em>То есть не злой, а этот, как его, ...</em> .","choices":["<em>страшный</em>","<em>ужасный</em>","<em>злопамятный</em>","<em>коварный</em>","<em>кровожадный</em>."],"key":"Г","review":["Света описывает поезд","Вспомни название поезда, который возит грузы. Такой поезд — товарный. Света могла забыть это слово и подобрать вместо него похожее.","У «товарный» и «коварный» совпадает почти всё слово. «Коварный» значит «способный хитростью причинить зло», поэтому понятна первая догадка Светы."]},{"author":"И. Иткин","question":"В какой паре слова надо поменять местами?","choices":["<em>ножницы</em> — <em>карандаши</em>","<em>лыжи</em> — <em>санки</em>","<em>грабли</em> — <em>лопаты</em>","<em>бусы</em> — <em>колечки</em>","<em>качели</em> — <em>карусели</em>."],"key":"Б","review":["Порядок слов в парах","Попробуй назвать в единственном числе второй предмет в каждой паре. Выходят «карандаш», «лопата», «колечко» и «карусель», а одни санки всё равно зовутся «санки».","В других парах слово, у которого нет формы единственного числа, стоит первым — одни ножницы, одни грабли, одни бусы, одни качели. Поэтому и «санки» надо поставить перед «лыжами», ведь одну лыжу можно назвать «лыжа»."]},{"author":"А. Леонтьева и Д. Леонтьева","question":"Маленькая Света, услышав в одной песне слова «...Из эмки стреляют...», спросила, что такое «эмка».\n<em>—</em> Это такая винтовка, <em>—</em> ответила старшая сестра.\n<em>—</em> А как из винтовки можно стрелять? <em>—</em> удивилась Света. <em>—</em> Ею же ... С чем Света перепутала винтовку?","choices":["с саблей","с лопаткой","с дубинкой","с молотком","с отвёрткой."],"key":"Д","review":["Что перепутала Света","Прислушайся к началу слова «винтовка». Оно похоже на «винт», поэтому Света могла решить, что речь про инструмент для винтов.","Винты закручивают или откручивают отвёрткой. Вероятно, именно её Света представляла, когда услышала слово «винтовка»."]},{"author":"И. Иткин","question":"В некоторых говорах вепсского языка есть слово venehlabid. Что означает это слово, если veneh по-вепсски ‘лодка’, labid <em>—</em> ‘лопата’?","choices":["совочек","руль","весло","парус","корма."],"key":"В","review":["Вепсское слово о лодке","Раздели «venehlabid» на данные части «veneh» и «labid». Вместе они дают понятный образ «лодочная лопата».","Лопатой назвали предмет с широкой плоской частью, которой гребут. Для этого в лодке используют весло."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
